import { durability } from "../engine/durability.ts";
/** Reproducible native scale receipt; every generated byte lives in one automatically removed directory. */
import assert from "node:assert/strict";
import { closeSync, cpSync, mkdtempSync, openSync, readSync, statSync, writeSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { traceFile } from "../engine/attribution.ts";
import { readFragmentRange } from "../engine/fragments.ts";
import { collectGarbage } from "../engine/gc.ts";
import { manifestFragments } from "../engine/manifest-pages.ts";
import { type Signature } from "../engine/model.ts";
import { Repository } from "../engine/repo.ts";
import { seededBytes } from "./cdc-benchmark.ts";

/** Measure physical compressed object bytes without retaining payload buffers. */
function storeBytes(repo: Repository): number {
  let size = 0;
  for (const entry of repo.objects.walkInventory()) size += statSync(entry.path).size;
  return size;
}

/** Commit a generated binary and a real tracker copy, edit 1%, verify ranges and measure conservative GC. */
export function benchmarkPhase6(tracker: string, byteLength: number) {
  const scratch = mkdtempSync(join(tmpdir(), "pm-vcs-scale-"));
  try {
    cpSync(tracker, join(scratch, ".agents/pm"), { recursive: true });
    const file = join(scratch, "generated.bin");
    const fd = openSync(file, "wx");
    try {
      for (let offset = 0; offset < byteLength; offset += 1_048_576) {
        const block = seededBytes(Math.min(1_048_576, byteLength - offset), 42 + offset);
        assert.equal(writeSync(fd, block), block.length);
      }
    } finally { closeSync(fd); }
    const repo = Repository.init(scratch, "main", { recordPaths: [".agents/pm/**/*.toon"], recordPolicy: {} });
    const author: Signature = { name: "Benchmark", email: "benchmark@example.invalid", timestamp: 1, timezoneOffsetMinutes: 0 };
    const started = performance.now(); repo.stage([]);
    const first = repo.commit({ message: "scale baseline", author, items: ["pm-vcs-b7cb"] }, new Date(1));
    const baselineWriteMs = performance.now() - started;
    const original = repo.readIndex().find(entry => entry.path === "generated.bin")!;
    const originalChunks = new Set([...manifestFragments(repo.objects, original.id)].map(part => part.fragment.id));
    const baselineStoreBytes = storeBytes(repo);
    const editBytes = Math.floor(byteLength / 100); const editOffset = Math.floor(byteLength / 2);
    durability.rename(file, join(scratch, "renamed.bin"));
    const edited = join(scratch, "renamed.bin"); const edit = seededBytes(editBytes, 12345);
    const output = openSync(edited, "r+");
    try { assert.equal(writeSync(output, edit, 0, edit.length, editOffset), edit.length); } finally { closeSync(output); }
    const editStarted = performance.now(); repo.stage(["renamed.bin"]);
    const second = repo.commit({ message: "rename and replace one percent", author, items: ["pm-vcs-b7cb"] }, new Date(2));
    const editedWriteMs = performance.now() - editStarted;
    const current = repo.readIndex().find(entry => entry.path === "renamed.bin")!;
    assert.equal(current.fileId, original.fileId);
    const chunks = [...manifestFragments(repo.objects, current.id)];
    const reused = chunks.filter(part => originalChunks.has(part.fragment.id));
    const editedStoreBytes = storeBytes(repo);
    const trace = traceFile(repo.objects, [second, first], current.fileId!);
    assert.deepEqual(trace.map(entry => entry.kind), ["moved", "added"]);
    assert.ok(trace.every(entry => entry.items.includes("pm-vcs-b7cb")));
    const latencies: number[] = [];
    for (let attempt = 0; attempt < 21; attempt++) {
      const start = Math.floor((byteLength - 4096) * attempt / 20);
      const before = performance.now(); const range = readFragmentRange(repo.objects, current.id, start, start + 4096);
      latencies.push(performance.now() - before);
      const expected = Buffer.alloc(4096); const input = openSync(edited, "r");
      try { assert.equal(readSync(input, expected, 0, expected.length, start), expected.length); } finally { closeSync(input); }
      assert.deepEqual(range, expected);
    }
    // Incomplete staging leaves unreferenced objects; both committed generations must survive collection.
    repo.objects.write("blob", seededBytes(1_048_576, 999));
    const dry = collectGarbage(repo); const applied = collectGarbage(repo, true);
    assert.equal(applied.reclaimedBytes, dry.candidateBytes);
    assert.equal(repo.objects.has(original.id), true); assert.equal(repo.objects.has(current.id), true);
    assert.equal(repo.verify().missing.length, 0);
    latencies.sort((left, right) => left - right);
    return { binaryBytes: byteLength, trackerFiles: repo.readIndex().length - 1, baselineStoreBytes, editedStoreBytes,
      addedStoreBytes: editedStoreBytes - baselineStoreBytes, editBytes, baselineWriteMs, editedWriteMs,
      originalChunks: originalChunks.size, editedChunks: chunks.length, reusedChunks: reused.length,
      reusedChunkRatio: reused.length / chunks.length, reusedByteRatio: reused.reduce((sum, part) => sum + part.fragment.length, 0) / byteLength,
      rangeBytes: 4096, rangeSamples: latencies.length, rangeMedianMs: latencies[10], rangeP95Ms: latencies[19],
      gcCandidateBytes: dry.candidateBytes, gcReclaimedBytes: applied.reclaimedBytes, retainedGenerations: 2 };
  } finally { durability.remove(scratch, { recursive: true, force: true }); }
}
